package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import java.util.*;
import static org.junit.Assert.*;
public class NativeReportStorageTest {
 @Test public void publicCreationCannotRequestTheInternalNativeReportBudget() throws Exception {try(var store=new WorkspaceStore(Files.createTempDirectory("native033-limits-"))){var args=new JSONObject().put("title","Untrusted request").put("nativeReport",true).put("fileLimit",2_000_000).put("files",new JSONObject().put("index.html","x".repeat(512_001)));assertThrows(IllegalArgumentException.class,()->store.write(args));assertEquals(0,store.artifacts().length());assertThrows(RuntimeException.class,()->store.writeNativePushOnce("invalid",new JSONObject().put("passed",true)));assertEquals(0,store.artifacts().length());}}
 @Test public void longActualNativeReportKeepsEveryOriginalByteAndDurableIdentity() throws Exception {var c=PushLearning.find(ContactStudy.suite(),"eval-z-axis");String id=UUID.randomUUID().toString();JSONObject run;try(var nativeStore=new ContactStore(Files.createTempDirectory("native033-report-run-"))){nativeStore.start(id,UUID.randomUUID().toString(),PushLearning.source(c,"report"),PushLearning.plan(ContactStudy.suite(),c,"report",8),false);for(int i=0;i<12000&&nativeStore.status(id).equals("running");i++)Thread.sleep(5);run=nativeStore.run(id);assertEquals("completed",run.getString("status"));}var expected=PushReport.build(run);boolean exceeded=false;for(String name:expected.getJSONObject("files").keySet())exceeded|=expected.getJSONObject("files").getString(name).length()>512_000;assertTrue("Real long contact data crosses the unchanged public creation cap",exceeded);var root=Files.createTempDirectory("native033-report-store-");String artifact;try(var store=new WorkspaceStore(root)){var a=store.writeNativePushOnce("real-native-report",run);artifact=a.getString("id");assertTrue(a.getJSONObject("contents").similar(expected.getJSONObject("files")));assertEquals(artifact,store.writeNativePushOnce("real-native-report",run).getString("id"));assertEquals(1,store.artifacts().length());}try(var store=new WorkspaceStore(root)){assertTrue(store.read(artifact).getJSONObject("contents").similar(expected.getJSONObject("files")));var packed=new JSONObject(store.read(artifact).getJSONObject("contents").getString("native-run.json"));byte[] raw;try(var in=new java.util.zip.GZIPInputStream(new java.io.ByteArrayInputStream(Base64.getDecoder().decode(packed.getString("gzipBase64"))))){raw=in.readAllBytes();}assertEquals(MapDefinition.sha(raw),packed.getString("rawSha256"));assertTrue(new JSONObject(new String(raw,java.nio.charset.StandardCharsets.UTF_8)).similar(run));}}
}
